exercises.solution:
class CharTokenizer:
    def __init__(self, text):
        self.chars = sorted(set(text))
        self.vocab_size = len(self.chars)
        self.stoi = {ch: i for i, ch in enumerate(self.chars)}
        self.itos = {i: ch for i, ch in enumerate(self.chars)}

    def encode(self, s):
        ids = []
        for ch in s:
            if ch not in self.stoi:
                raise ValueError(f"unknown character: {ch!r}")
            ids.append(self.stoi[ch])
        return ids

    def decode(self, ids):
        return "".join(self.itos[i] for i in ids)

def split_data(ids, train_fraction):
    n = int(len(ids) * train_fraction)
    return ids[:n], ids[n:]

def count_bigrams(ids, vocab_size):
    counts = [[0] * vocab_size for _ in range(vocab_size)]
    for i in range(len(ids) - 1):
        counts[ids[i]][ids[i + 1]] += 1
    return counts

def to_probs(row):
    total = sum(row)
    if total == 0:
        return [1 / len(row)] * len(row)
    return [c / total for c in row]

