def sample(probs, rng):
    r = rng.random()
    running = 0.0
    for i, p in enumerate(probs):
        running += p
        if r < running:
            return i
    return len(probs) - 1


def generate(counts, start_id, length, rng):
    out = [start_id]
    while len(out) < length:
        out.append(sample(to_probs(counts[out[-1]]), rng))
    return out

