def level_order(root):
    out = []
    level = [root] if root else []
    while level:
        out.append([n.value for n in level])
        nxt = []
        for n in level:
            if n.left:
                nxt.append(n.left)
            if n.right:
                nxt.append(n.right)
        level = nxt
    return out

