        return TreeNode(value)
    if value < root.value:
        root.left = bst_insert(root.left, value)
    elif value > root.value:
        root.right = bst_insert(root.right, value)
    return root


def bst_contains(root, value):
    while root:
        if value == root.value:
            return True
        root = root.left if value < root.value else root.right
    return False

