def count_islands(grid):
    seen = set()
    count = 0
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            count += 1
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                for ny, nx in ((y + 1, x), (y - 1, x), (y, x + 1), (y, x - 1)):
                    if 0 <= ny < len(grid) and 0 <= nx < len(grid[ny]) and grid[ny][nx] == 1 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
    return count

from collections import deque


def shortest_path(graph, start, goal):
    if start == goal:
        return 0
    seen = {start}
    queue = deque([(start, 0)])
    while queue:
        node, dist = queue.popleft()
        for nxt in graph.get(node, []):
            if nxt == goal:
                return dist + 1
            if nxt not in seen:
                seen.add(nxt)
                queue.append((nxt, dist + 1))
    return -1

def cheapest_flight(n, flights, src, dst, k):
    unreachable = float('inf')
    cost = [unreachable] * n
    cost[src] = 0
    for _ in range(k + 1):
        new = cost[:]
        for a, b, price in flights:
            if cost[a] != unreachable and cost[a] + price < new[b]:
                new[b] = cost[a] + price
        cost = new
    return -1 if cost[dst] == unreachable else cost[dst]

def mst_cost(n, edges):
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    total = 0
    used = 0
    for u, v, cost in sorted(edges, key=lambda e: e[2]):
        ru, rv = find(u), find(v)
        if ru != rv:
            parent[ru] = rv
            total += cost
            used += 1
    if n > 0 and used != n - 1:
        return None
    return total

def all_pairs(n, roads):
    inf = float('inf')
    dist = [[0 if i == j else inf for j in range(n)] for i in range(n)]
    for u, v, length in roads:
        if length < dist[u][v]:
            dist[u][v] = length
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]
    return [[None if v == inf else v for v in row] for row in dist]

def to_csr(dense):
    values, cols, row_ptr = [], [], [0]
    for row in dense:
        for c, v in enumerate(row):
            if v != 0:
                values.append(v)
                cols.append(c)
        row_ptr.append(len(values))
    return values, cols, row_ptr

