    y = []
    for r in range(len(row_ptr) - 1):
        total = 0
        for k in range(row_ptr[r], row_ptr[r + 1]):
            total += values[k] * x[cols[k]]
        y.append(total)
    return y

def circulant_matvec(c, x):
    n = len(c)
    return [sum(c[(j - i) % n] * x[j] for j in range(n)) for i in range(n)]

