def filter_probs(probs, k=None, p=None):
    order = sorted(range(len(probs)), key=lambda t: (-probs[t], t))
    if k is not None:
        order = order[:k]
    if p is not None:
        kept, total = [], 0.0
        for t in order:
            kept.append(t)
            total += probs[t]
            if total >= p - 1e-12:
                break
        order = kept
    total = sum(probs[t] for t in order)
    return {t: probs[t] / total for t in order}

