def greedy(next_logprobs, start, steps):
    seq, total = [start], 0.0
    for _ in range(steps):
        options = next_logprobs(seq)
        tok = min(options, key=lambda t: (-options[t], t))
        seq = seq + [tok]
        total += options[tok]
    return seq, round(total, 4)


def beam_search(next_logprobs, start, steps, width):
    beams = [(0.0, [start])]
    for _ in range(steps):
        cands = []
        for total, seq in beams:
            for tok, lp in next_logprobs(seq).items():
                cands.append((total + lp, seq + [tok]))
        cands.sort(key=lambda c: (-c[0], c[1]))
        beams = cands[:width]
    total, seq = beams[0]
    return seq, round(total, 4)

