import math


def attend(q, keys, values):
    d = len(q)
    scores = [sum(a * b for a, b in zip(q, k)) / math.sqrt(d) for k in keys]
    m = max(scores)
    e = [math.exp(s - m) for s in scores]
    total = sum(e)
    w = [x / total for x in e]
    return [sum(wi * v[j] for wi, v in zip(w, values)) for j in range(len(values[0]))]


def causal_attention(Q, K, V):
    return [attend(Q[t], K[:t + 1], V[:t + 1]) for t in range(len(Q))]


class KVCache:
    def __init__(self):
        self.keys, self.values = [], []

    def step(self, q, k, v):
        self.keys.append(k)
        self.values.append(v)
        return attend(q, self.keys, self.values)

    def __len__(self):
        return len(self.keys)

