def quantize(xs):
    m = max(abs(x) for x in xs)
    scale = m / 127 if m > 0 else 1.0
    q = [max(-127, min(127, round(x / scale))) for x in xs]
    return q, scale


def dequantize(q, scale):
    return [v * scale for v in q]


def mean_error(rows, per_row):
    groups = rows if per_row else [[v for r in rows for v in r]]
    total, n = 0.0, 0
    for g in groups:
        q, s = quantize(g)
        for a, b in zip(g, dequantize(q, s)):
            total += abs(a - b)
            n += 1
    return total / n

