def rrf(rankings, k=60):
    score = {}
    for ranking in rankings:
        for r, doc in enumerate(ranking, start=1):
            score[doc] = score.get(doc, 0.0) + 1.0 / (k + r)
    items = sorted(score.items(), key=lambda p: (-p[1], p[0]))
    return [(d, round(s, 6)) for d, s in items]

def mmr(query_sims, doc_sims, k, lam):
    n = len(query_sims)
    picked = []
    while len(picked) < min(k, n):
        best, best_score = None, None
        for d in range(n):
            if d in picked:
                continue
            if picked:
                redundancy = max(doc_sims[d][s] for s in picked)
                score = lam * query_sims[d] - (1 - lam) * redundancy
            else:
                score = query_sims[d]
            if best_score is None or score > best_score:
                best, best_score = d, score
        picked.append(best)
    return picked

def pack_context(chunks, budget):
    order = sorted(range(len(chunks)), key=lambda i: (-chunks[i][0], i))
    chosen, used = [], 0
    for i in order:
        score, tokens, text = chunks[i]
        if used + tokens <= budget:
            chosen.append(text)
            used += tokens
    front, back = [], []
    for n, text in enumerate(chosen):
        (front if n % 2 == 0 else back).append(text)
    return front + back[::-1]

