import math


def margin(pi_c, pi_r, ref_c, ref_r, beta):
    return beta * ((pi_c - ref_c) - (pi_r - ref_r))


def dpo_loss(pi_c, pi_r, ref_c, ref_r, beta):
    z = margin(pi_c, pi_r, ref_c, ref_r, beta)
    if z >= 0:
        return math.log1p(math.exp(-z))
    return -z + math.log1p(math.exp(z))

