exercises.solution:
import json

TYPES = {
    'string': lambda v: isinstance(v, str),
    'integer': lambda v: isinstance(v, int) and not isinstance(v, bool),
    'number': lambda v: isinstance(v, (int, float)) and not isinstance(v, bool),
    'boolean': lambda v: isinstance(v, bool),
}


def check_call(text, tools):
    try:
        call = json.loads(text)
    except ValueError:
        return 'error: not valid JSON'
    if not isinstance(call, dict) or not isinstance(call.get('name'), str) or not isinstance(call.get('arguments'), dict):
        return 'error: not valid JSON'
    name, args = call['name'], call['arguments']
    if name not in tools:
        return 'error: unknown tool ' + name
    params, required = tools[name]['params'], tools[name]['required']
    extra = sorted(set(args) - set(params))
    if extra:
        return 'error: unexpected argument ' + extra[0]
    for r in required:
        if r not in args:
            return 'error: missing argument ' + r
    for p, kind in params.items():
        if p in args and not TYPES[kind](args[p]):
            return 'error: argument %s must be %s' % (p, kind)
    return 'ok'

