def run_agent(model, tools, task, max_steps):
    history = [('user', task)]
    for steps in range(1, max_steps + 1):
        out = model(history)
        if 'answer' in out:
            return (out['answer'], steps)
        name, args = out['tool'], out.get('args', {})
        history.append(('call', name, args))
        fn = tools.get(name)
        if fn is None:
            value = 'error: unknown tool'
        else:
            try:
                value = fn(**args)
            except Exception as e:
                value = 'error: ' + str(e)
        history.append(('result', name, value))
    return ('stopped: step limit', max_steps)

