from collections import OrderedDict


class PromptCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.store = OrderedDict()
        self.hits = self.misses = 0

    def _key(self, prompt, model):
        return (model, ' '.join(prompt.lower().split()))

    def get(self, prompt, model, temperature):
        if temperature != 0:
            return None
        key = self._key(prompt, model)
        if key in self.store:
            self.hits += 1
            self.store.move_to_end(key)
            return self.store[key]
        self.misses += 1
        return None

    def put(self, prompt, model, temperature, answer):
        if temperature != 0:
            return
        key = self._key(prompt, model)
        self.store[key] = answer
        self.store.move_to_end(key)
        if len(self.store) > self.capacity:
            self.store.popitem(last=False)

import json


def read_stream(chunks):
    buffer, answer = '', []
    for chunk in chunks:
        buffer += chunk
        while '\n' in buffer:
            line, buffer = buffer.split('\n', 1)
            if not line or line.startswith(':'):
                continue
            if line.startswith('data: '):
                payload = line[len('data: '):]
                if payload == '[DONE]':
                    return ''.join(answer)
                answer.append(json.loads(payload).get('delta', ''))
    return ''.join(answer)

