import random


def perm_test(a, b, n_perm, seed):
    mean = lambda v: sum(v) / len(v)
    observed = abs(mean(b) - mean(a))
    pooled = list(a) + list(b)
    rng = random.Random(seed)
    count = 0
    for _ in range(n_perm):
        rng.shuffle(pooled)
        stat = abs(mean(pooled[len(a):]) - mean(pooled[:len(a)]))
        if stat >= observed - 1e-12:
            count += 1
    return (round(observed, 4), round((count + 1) / (n_perm + 1), 4))

