def holm(pvals, alpha=0.05):
    m = len(pvals)
    out = [False] * m
    order = sorted(range(m), key=lambda i: (pvals[i], i))
    for i, idx in enumerate(order):
        if pvals[idx] <= alpha / (m - i):
            out[idx] = True
        else:
            break
    return out


def bonferroni(pvals, alpha=0.05):
    m = len(pvals)
    return [p <= alpha / m for p in pvals]

