import math


def fit_scaler(xs):
    m = sum(xs) / len(xs)
    sd = math.sqrt(sum((x - m) ** 2 for x in xs) / len(xs))
    return (m, sd if sd > 0 else 1.0)


def transform(xs, scaler):
    m, sd = scaler
    return [(x - m) / sd for x in xs]


def leak_gap(train, valid):
    mean = lambda v: sum(v) / len(v)
    honest = transform(valid, fit_scaler(train))
    leaky = transform(valid, fit_scaler(list(train) + list(valid)))
    return round(mean(honest) - mean(leaky), 4)

def roc_auc(labels, scores):
    pos = [s for y, s in zip(labels, scores) if y == 1]
    neg = [s for y, s in zip(labels, scores) if y == 0]
    if not pos or not neg:
        return 0.5
    total = 0.0
    for p in pos:
        for q in neg:
            total += 1.0 if p > q else 0.5 if p == q else 0.0
    return total / (len(pos) * len(neg))

