def log_loss(labels, probs, eps=1e-15):
    total = 0.0
    for y, p in zip(labels, probs):
        p = min(max(p, eps), 1 - eps)
        total += -(y * math.log(p) + (1 - y) * math.log(1 - p))
    return total / len(labels)


def brier(labels, probs):
    return sum((p - y) ** 2 for y, p in zip(labels, probs)) / len(labels)

def best_threshold(labels, scores, cost_fp, cost_fn):
    best = None
    for t in sorted(set(scores)) + [float('inf')]:
        fp = sum(1 for y, s in zip(labels, scores) if y == 0 and s >= t)
        fn = sum(1 for y, s in zip(labels, scores) if y == 1 and s < t)
        cost = fp * cost_fp + fn * cost_fn
        if best is None or cost <= best[1]:
            best = (t, cost)
    return best

