import random


def map_reduce(records, mapper, reducer, combiner=None, workers=3):
    """Run a job the way Hadoop does.

    Each record is mapped on one of the workers. If there is a
    combiner, each worker runs it on its own pairs. Then all pairs
    are grouped by key and each key is reduced once.
    """
    rng = random.Random(len(records))
    parts = [[] for _ in range(workers)]
    for record in records:
        parts[rng.randrange(workers)].append(record)
    pairs = []
    for part in parts:
        local = {}
        for record in part:
            for key, value in mapper(record):
                local.setdefault(key, []).append(value)
        for key, values in local.items():
            if combiner:
                pairs.extend(combiner(key, values))
            else:
                pairs.extend((key, v) for v in values)
    rng.shuffle(pairs)
    groups = {}
    for key, value in pairs:
        groups.setdefault(key, []).append(value)
    return sorted(reducer(k, v) for k, v in groups.items())

