def bisect_root(f, lo, hi, tol):
    f_lo = f(lo)
    while hi - lo > tol:
        mid = (lo + hi) / 2
        fm = f(mid)
        if fm == 0:
            return mid
        if f_lo * fm > 0:
            lo, f_lo = mid, fm
        else:
            hi = mid
    return (lo + hi) / 2

def newton(f, df, x0, steps):
    x = x0
    for _ in range(steps):
        x = x - f(x) / df(x)
    return x

