def forward_diff(f, x, h):
    return (f(x + h) - f(x)) / h


def central_diff(f, x, h):
    return (f(x + h) - f(x - h)) / (2 * h)

def trapezoid(f, a, b, n):
    h = (b - a) / n
    total = (f(a) + f(b)) / 2
    for i in range(1, n):
        total += f(a + i * h)
    return h * total

def simpson(f, a, b, n):
    h = (b - a) / n
    total = f(a) + f(b)
    for i in range(1, n):
        total += (4 if i % 2 else 2) * f(a + i * h)
    return h / 3 * total

def lagrange(xs, ys, x):
    total = 0
    for i in range(len(xs)):
        term = ys[i]
        for j in range(len(xs)):
            if j != i:
                term *= (x - xs[j]) / (xs[i] - xs[j])
        total += term
    return total

def back_substitute(U, b):
    n = len(b)
    x = [0.0] * n
    for i in range(n - 1, -1, -1):
        s = 0
        for j in range(i + 1, n):
            s += U[i][j] * x[j]
        x[i] = (b[i] - s) / U[i][i]
    return x

def lu(A):
    n = len(A)
    U = [[float(v) for v in row] for row in A]
    L = [[1.0 if i == j else 0.0 for j in range(n)] for i in range(n)]
    for k in range(n):
        for r in range(k + 1, n):
            factor = U[r][k] / U[k][k]
            L[r][k] = factor
            for c in range(k, n):
                U[r][c] -= factor * U[k][c]
    return L, U

def jacobi(A, b, steps):
    n = len(b)
    x = [0.0] * n
    for _ in range(steps):
        new_x = []
        for i in range(n):
            s = 0
            for j in range(n):
                if j != i:
                    s += A[i][j] * x[j]
            new_x.append((b[i] - s) / A[i][i])
        x = new_x
    return x

def gauss_seidel(A, b, tol):
    n = len(b)
    x = [0.0] * n
    sweeps = 0
    while True:
        change = 0.0
        for i in range(n):
            s = 0
            for j in range(n):
                if j != i:
                    s += A[i][j] * x[j]
            new = (b[i] - s) / A[i][i]
            change = max(change, abs(new - x[i]))
            x[i] = new
        sweeps += 1
        if change < tol:
            return x, sweeps

def after_steps(P, start, steps):
    n = len(start)
    dist = list(start)
    for _ in range(steps):
        dist = [sum(dist[i] * P[i][j] for i in range(n)) for j in range(n)]
    return dist

def stationary(P, tol):
    n = len(P)
    dist = [1 / n] * n
    while True:
        new = [sum(dist[i] * P[i][j] for i in range(n)) for j in range(n)]
        change = max(abs(new[j] - dist[j]) for j in range(n))
        dist = new
        if change <= tol:
            return dist

def mm1(lam, mu):
    if lam >= mu:
        return None
    rho = lam / mu
    return {"rho": rho, "L": rho / (1 - rho), "Lq": rho * rho / (1 - rho), "W": 1 / (mu - lam), "Wq": rho / (mu - lam)}

def pagerank(links, d, steps):
    n = len(links)
    rank = [1 / n] * n
    for _ in range(steps):
        dangling = sum(rank[i] for i in range(n) if not links[i])
        new = [(1 - d) / n + d * dangling / n] * n
        for i in range(n):
            for j in links[i]:
                new[j] += d * rank[i] / len(links[i])
        rank = new
    return rank

def top_singular(A, steps):
    rows, cols = len(A), len(A[0])

    def norm(x):
        return sum(t * t for t in x) ** 0.5

    def times(v):
        return [sum(A[i][j] * v[j] for j in range(cols)) for i in range(rows)]

    v = [1 / cols ** 0.5] * cols
    for _ in range(steps):
        w = times(v)
        u = [sum(A[i][j] * w[i] for i in range(rows)) for j in range(cols)]
        size = norm(u)
        v = [t / size for t in u]
    return norm(times(v)), v
